mapper.select:
/* 대국민포털_메인화면 최근 게시물 조회 (SNS 통합) (MainMapper.selectRecent20PstListByTaskCds) */ SELECT p.pst_sn ,p.bbs_id ,p.pst_ttl ,p.thmb_id ,f.srvr_file_nm as thmb_file_nm ,p.reg_dt ,p.pst_cn ,p.vdo_url_addr as video_id ,t.task_cd ,CASE t.task_cd WHEN 'MN_BBS2' THEN '유튜브' WHEN 'MN_BBS3' THEN '인스타' WHEN 'MN_BBS4' THEN '블로그' ELSE '기타' END AS sns_type ,p.thmb_expln_cn ,p.vdo_expln_cn FROM kids_own.TB_PP_M_BBS b , kids_own.TB_PP_M_BBS_AUTHRT ba , kids_own.TB_PP_M_TASK_CD t LEFT JOIN kids_own.TB_PP_M_PST p ON t.task_cd_vl = p.bbs_id LEFT JOIN kids_own.TB_CA_E_FILE_TRSM f ON f.atch_file_group_id = p.thmb_id AND f.atch_file_id = (SELECT MAX(atch_file_id) FROM kids_own.tb_ca_e_file_trsm WHERE atch_file_group_id = p.thmb_id) WHERE t.task_cd IN
#{taskCd}
AND b.bbs_id = p.bbs_id AND ba.authrt_cd = 'BBS_USR' AND b.bbs_id = ba.bbs_id AND b.use_yn = 'Y' AND p.expsr_yn = 'Y' ORDER BY p.reg_dt DESC LIMIT 20

/* 대국민포털_메인화면 업무구분코드에 따른 URL 정보 반환 (MainMapper.selectBbsUrlInfosByTaskCds) */ SELECT tc.task_cd , mm.menu_nm , dm.menu_url_addr FROM kids_own.tb_pp_m_task_cd tc , kids_own.tb_pp_d_menu dm , kids_own.tb_pp_m_menu mm WHERE tc.task_cd IN
#{cd}
AND mm.task_se_cd = 'PP' AND mm.menu_type_cd = 'U' AND mm.menu_sn = dm.menu_sn AND split_part(dm.menu_url_addr, '/', array_length(string_to_array(dm.menu_url_addr, '/'), 1)) = tc.task_cd_vl

/* 대국민포털_메인화면 팝업 목록 조회 (MainMapper.selectPopupList) */ SELECT p.popup_ttl , p.popup_lnkg_addr , f.srvr_file_nm as thmb_file_nm FROM kids_own.TB_PP_M_POPUP p LEFT OUTER JOIN kids_own.TB_CA_E_FILE_TRSM f ON f.atch_file_group_id = p.atch_file_group_id AND f.atch_file_id = (SELECT MAX(atch_file_id) FROM kids_own.tb_ca_e_file_trsm WHERE atch_file_group_id = p.atch_file_group_id) WHERE p.popup_pstg_yn = 'Y'
AND (p.popup_pstg_bgng_dt <= CURRENT_TIMESTAMP AND p.popup_pstg_end_dt >= CURRENT_TIMESTAMP)
ORDER BY p.popup_seq
